struct CallInfo{std::vector<std::optional<std::string>> argument_types;};
std::optional<std::string> literal_token_type(const std::vector<Token>& tokens,std::size_t begin,std::size_t end){if(end!=begin+1)return std::nullopt;const auto& token=tokens[begin];if(token.kind==TokenKind::integer_literal)return infer_integer_literal(token.lexeme).name;if(token.kind==TokenKind::floating_literal)return infer_floating_literal(token.lexeme).name;if(token.kind==TokenKind::string_literal)return "string";if(token.kind==TokenKind::boolean_literal)return "bool";if(token.kind==TokenKind::null_literal)return "null";return std::nullopt;}
