std::string canonical_type(std::string type){if(type=="int")return "int_32";if(type=="uint")return "uint_32";if(type=="double")return "double_32";return type;}
bool literal_compatible(const std::string& actual,const std::string& expected){const auto want=canonical_type(expected);if(actual==want)return true;if(actual=="null")return !want.empty()&&want.back()=='?';return can_implicitly_convert(builtin_type(actual),builtin_type(want));}
